// Extract channels from Slack API response
const response = $input.first().json;

if (!response.ok) {
  throw new Error(`Slack API Error: ${response.error}`);
}

const channels = response.channels || [];
const oneDayAgo = Math.floor((Date.now() - 86400000) / 1000);

// Map each channel to include query parameters
const output = channels.map(channel => ({
  channelId: channel.id,
  channelName: channel.name || channel.user || 'DM',
  isChannel: channel.is_channel || false,
  isGroup: channel.is_group || false,
  isIm: channel.is_im || false,
  isMpim: channel.is_mpim || false,
  oldest: oneDayAgo.toString()
}));

return output;

// Process Slack messages and format for Google Sheets
const items = $input.all();
const output = [];

for (const item of items) {
  const response = item.json;
  const channelName = $node['Process Channels'].json.channelName;

  if (!response.ok) {
    console.log(`Error for channel ${channelName}: ${response.error}`);
    continue;
  }

  const messages = response.messages || [];

  for (const message of messages) {
    // Skip bot messages if desired (remove this if you want bot messages)
    // if (message.bot_id && !message.user) continue;

    // Convert timestamp
    const timestamp = parseFloat(message.ts) * 1000;
    const date = new Date(timestamp);

    // Format date/time
    const formattedDate = date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit'
    });
    const formattedTime = date.toLocaleTimeString('en-US', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: true
    });

    // Get user
    const user = message.user || message.bot_id || message.username || 'Unknown';

    // Get message text
    const text = message.text || '';

    // Check if thread reply
    const isThreadReply = message.thread_ts && message.thread_ts !== message.ts;

    // Get reactions
    const reactions = message.reactions 
      ? message.reactions.map(r => `${r.name} (${r.count})`).join(', ')
      : '';

    // Check attachments
    const hasFiles = (message.files && message.files.length > 0);
    const hasAttachments = (message.attachments && message.attachments.length > 0);
    const attachmentCount = (message.files?.length || 0) + (message.attachments?.length || 0);

    output.push({
      date: formattedDate,
      time: formattedTime,
      channel: channelName,
      user: user,
      message: text,
      threadReply: isThreadReply ? 'Yes' : 'No',
      reactions: reactions,
      attachments: attachmentCount > 0 ? `${attachmentCount} file(s)` : 'None',
      timestamp: message.ts
    });
  }
}

return output;
